import{_ as o,C as r,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"First steps: hire your first employee","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/get-started/first-steps.md","filePath":"master/human-resources/recruitment/get-started/first-steps.md","lastUpdated":1791902625000}'),l={name:"master/human-resources/recruitment/get-started/first-steps.md"};function p(h,e,c,g,d,u){const a=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="first-steps-hire-your-first-employee" tabindex="-1">First steps: hire your first employee <a class="header-anchor" href="#first-steps-hire-your-first-employee" aria-label="Permalink to &quot;First steps: hire your first employee&quot;">​</a></h1><p>This tutorial follows one applicant from first contact to employee. You check the setup, add the applicant, move him through the stages and create his employee profile. Then you refuse a second applicant and bring her back. The example is a hire for the job position <strong>Warehouse Supervisor</strong>.</p><blockquote><p><strong>In simple words:</strong> An applicant is a person who applies for a job. You move that person through stages until you hire or refuse them.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>The stages and the job position <strong>Warehouse Supervisor</strong> exist in the sample data. You need a user to act as recruiter. This tutorial uses <strong>ERP Admin</strong>.</p></div><h2 id="step-1-check-the-stages" tabindex="-1">Step 1: Check the stages <a class="header-anchor" href="#step-1-check-the-stages" aria-label="Permalink to &quot;Step 1: Check the stages&quot;">​</a></h2><p>Stages are the steps every applicant passes through.</p><ol><li>Open <code>Recruitments → Configuration → Stages</code>.</li><li>Read the <strong>Stage Name</strong> column. The list shows the last stage first. The applicant screen shows the real order: <strong>New</strong>, <strong>First Interview</strong>, <strong>Initial Qualification</strong>, <strong>Second Interview</strong>, <strong>Document Verification</strong>, <strong>Contract Proposal</strong>, <strong>Contract Signed</strong>.</li><li>Find <strong>Contract Signed</strong>. Its <strong>Hired Stage</strong> column says <strong>Yes</strong>. An applicant who reaches this stage counts as hired.</li></ol>',7)),s(a,{src:"/images1/recruitment/gs_stages_list.png",alt:"Stages list with Contract Signed marked Yes in the Hired Stage column"}),e[1]||(e[1]=t('<p>See <a href="./../setup/stages.html">Stages</a> to add or change them.</p><h2 id="step-2-check-the-job-position" tabindex="-1">Step 2: Check the job position <a class="header-anchor" href="#step-2-check-the-job-position" aria-label="Permalink to &quot;Step 2: Check the job position&quot;">​</a></h2><ol><li>Open <code>Recruitments → Applications → Job Positions</code>.</li><li>Go to page 2 of the cards, or type <strong>Warehouse Supervisor</strong> in the search box.</li><li>Read the card. The blue button shows how many applicants are in the <strong>New</strong> stage. The three dots menu shows <strong>To Recruitment</strong> and <strong>Applications</strong>.</li></ol>',3)),s(a,{src:"/images1/recruitment/gs_jobpos_card.png",alt:"Job position card for Warehouse Supervisor with the New Applications button and the three dots menu"}),e[2]||(e[2]=t('<p>See <a href="./../job-positions/job-positions.html">Job positions</a> for the card details.</p><h2 id="step-3-add-the-applicant" tabindex="-1">Step 3: Add the applicant <a class="header-anchor" href="#step-3-add-the-applicant" aria-label="Permalink to &quot;Step 3: Add the applicant&quot;">​</a></h2><ol><li>Open <code>Recruitments → Applications → Applicants</code>.</li><li>Click <strong>New Applicant</strong>. A <strong>Create Applicant</strong> window opens.</li><li>Open the <strong>Candidate</strong> field and use the create option to add a new person.</li><li>Type <strong>Rahul Verma</strong> as <strong>Full Name</strong>. Add the email <strong><a href="mailto:rahul.verma@example.com" target="_blank" rel="noreferrer">rahul.verma@example.com</a></strong> and a phone number.</li><li>Save the candidate, then click <strong>Create</strong>.</li></ol><p>The edit page of the applicant opens. The applicant starts in the stage <strong>New</strong>, because that stage is the default.</p><h2 id="step-4-fill-in-the-applicant" tabindex="-1">Step 4: Fill in the applicant <a class="header-anchor" href="#step-4-fill-in-the-applicant" aria-label="Permalink to &quot;Step 4: Fill in the applicant&quot;">​</a></h2><ol><li>Set <strong>Job Positions</strong> to <strong>Warehouse Supervisor</strong>.</li><li>Set <strong>Recruiter</strong> to <strong>ERP Admin</strong> and add an <strong>Interviewer</strong>.</li><li>Add a <strong>Tags</strong> value, a <strong>Degree</strong> and an <strong>Availability Date</strong>.</li><li>Enter <strong>Expected Salary</strong> <strong>40000</strong>.</li><li>Choose <strong>Source</strong> and <strong>Medium</strong>, for example <strong>LinkedIn</strong>.</li><li>Click the stars to rate the applicant. Click <strong>Save changes</strong>.</li></ol><p>Each field is explained in <a href="./../applicants/add-applicant.html">Add an applicant</a>.</p><h2 id="step-5-set-the-state-and-move-through-the-stages" tabindex="-1">Step 5: Set the state and move through the stages <a class="header-anchor" href="#step-5-set-the-state-and-move-through-the-stages" aria-label="Permalink to &quot;Step 5: Set the state and move through the stages&quot;">​</a></h2><p>The state tells your team how an applicant is doing inside a stage.</p><ol><li>Click the <strong>State</strong> icon button in the page header.</li><li>Choose <strong>Ready for next stage</strong> and click <strong>Submit</strong>.</li></ol><ol start="3"><li>Click <strong>First Interview</strong> in the stage bar. The stage changes at once.</li><li>Keep clicking the next stage as the hiring goes on, up to <strong>Contract Proposal</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Moving to a new stage resets the state to <strong>In Progress</strong>.</p></div><h2 id="step-6-hire-the-applicant" tabindex="-1">Step 6: Hire the applicant <a class="header-anchor" href="#step-6-hire-the-applicant" aria-label="Permalink to &quot;Step 6: Hire the applicant&quot;">​</a></h2><ol><li>Click <strong>Contract Signed</strong> in the stage bar.</li><li>Check the <strong>Application status</strong> pill. It now says <strong>Hired</strong>.</li></ol><h2 id="step-7-create-the-employee" tabindex="-1">Step 7: Create the employee <a class="header-anchor" href="#step-7-create-the-employee" aria-label="Permalink to &quot;Step 7: Create the employee&quot;">​</a></h2><ol><li>Click <strong>Create Employee</strong> in the page header.</li><li>The employee page opens. Review the profile and save it.</li><li>Go back to the applicant. The button is now <strong>Go to Employee</strong>. Click it to open the profile.</li></ol><p>See <a href="./../../employees/employees/employee-profile.html">Employee profile</a> for what to fill in next.</p><h2 id="step-8-refuse-and-restore-an-applicant" tabindex="-1">Step 8: Refuse and restore an applicant <a class="header-anchor" href="#step-8-refuse-and-restore-an-applicant" aria-label="Permalink to &quot;Step 8: Refuse and restore an applicant&quot;">​</a></h2><p>Add a second applicant, <strong>Meera Nair</strong>, for <strong>Warehouse Supervisor</strong> the same way.</p><ol><li>Open Meera&#39;s applicant page and click <strong>Refuse</strong>.</li><li>Choose the reason <strong>Refused by applicant: salary</strong>.</li><li>Leave <strong>Notify</strong> on. <strong>Email To</strong> shows her email address. Click <strong>Submit</strong>.</li></ol><ol start="4"><li>Check the applicant. The status is <strong>Refused</strong> and the stage bar is hidden.</li></ol><ol start="5"><li>To bring her back, click <strong>Restore</strong> and confirm.</li></ol><p>See <a href="./../applicants/refuse-and-reopen.html">Refuse and reopen</a> for the details.</p><h2 id="step-9-find-the-applicants-on-the-list" tabindex="-1">Step 9: Find the applicants on the list <a class="header-anchor" href="#step-9-find-the-applicants-on-the-list" aria-label="Permalink to &quot;Step 9: Find the applicants on the list&quot;">​</a></h2><ol><li>Open <code>Recruitments → Applications → Applicants</code>.</li><li>The list is grouped by stage. Find the group of each applicant.</li><li>Open the three dots menu and apply the <strong>Hired</strong> view to see hired people.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../applicants/process-applicant.html">Process an applicant</a></li><li><a href="./../applicants/applicant-list.html">Applicant list</a></li><li><a href="./../dashboard/recruitment-dashboard.html">Recruitment dashboard</a></li><li><a href="./../../employees/">Employees overview</a></li></ul>',27))])}const b=o(l,[["render",p]]);export{f as __pageData,b as default};
